programs.haiku:
"""Layer 15 MLP down_proj, component 4353: an answer-polarity detector.

The component is quiet almost everywhere. Its large values are negative, and they fall on
the words a speaker uses to answer a yes/no question or to affirm or deny a claim:
  - "Yes", "yeah", "oui", "да" and similar: strongest, about -5.
  - "indeed", "definitely", "sure", "agree", "correct", "true": about -0.7 each.
  - "No", "nope", and stance words such as "actually", "unfortunately", "false": about -0.6.
  - "do", "does", "did" used as the main verb of an answer, right after a subject ("I do",
    "it does"): about -4. Elsewhere they are weakly negative, about -1.
  - "not" after a form of be or an auxiliary ("is not", "does not"): about -1.5. Other "not"
    is near zero.
  - A comma straight after a yes or no ("Yes, ..."): about -4.
  - "but" is weakly positive, +0.5, as contrast words tend to be.

The program reads the current token and the one before it. Its values are the
least-squares magnitudes for these groups on sampled training rows. It ignores the wider
context, so on eval rows it explains about 5% of the variance (r about 0.23). Most of the
rest is spread over many tokens with small values, which a short word list cannot name.
"""

READS = ()

YES_WORDS = {"yes", "yeah", "yep", "oui", "да", "もちろん", "当然", "确实"}
OTHER_AFFIRM = {"ja", "sí", "si", "sim", "indeed", "definitely", "certainly", "absolutely",
                "sure", "agree", "correct", "true"}
NO_WORDS = {"no", "nope"}
STANCE = {"actually", "obviously", "really", "truly", "clearly", "unfortunately", "okay",
          "false", "wrong", "incorrect", "valid", "right", "still"}
SUBJECTS = {"i", "we", "you", "they", "he", "she", "it", "that", "who", "people"}
BE_OR_AUX = {"is", "are", "was", "were", "am", "do", "does", "did", "will"}
AUXILIARIES = {"do", "does", "did"}


def word(text):
    """The token as a bare lowercase word: no spaces, quotes or punctuation."""
    return text.strip().strip("\"“”'‘’(),.!?:;").lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    w = word(tokens[-1])
    same_doc = len(tokens) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    p = word(tokens[-2]) if same_doc else ""
    if w in YES_WORDS:
        v = -5.0
    elif w in OTHER_AFFIRM:
        v = -0.7
    elif w in NO_WORDS or w in STANCE:
        v = -0.6
    elif w in AUXILIARIES:
        v = -3.9 if p in SUBJECTS else -1.0
    elif w == "not":
        v = -1.5 if p in BE_OR_AUX else -0.2
    elif w == "but":
        v = 0.5
    elif tokens[-1].strip() == "," and p in ("yes", "no", "yeah", "ja", "oui"):
        v = -3.8
    else:
        v = 0.0
    return carry, v

"""Disjunction and inference connectives, layer 15 MLP down_proj component 4358.

The component fires on the word that joins two alternatives: "or" most strongly
(about 6.4), and "or" in other languages more weakly (ou, oder, или, 或, hoặc, atau,
eller, ... about 2.4). It fires weakly on words that introduce a conclusion
("therefore", "thus", "hence", "so", about 1.9), and weakly on operators and
comparisons that join two terms ("+", "-", "/", "than", "as", about 0.8).
Everything else is predicted as 0.

The program outputs a fixed value per word class, so it reads the newest token only.
"""

READS = ()

# The word "or" itself: the strongest case.
OR = {"or"}
# Other words that join two alternatives ("A or B"), in other languages.
OTHER_DISJUNCTION = {
    "nor", "ou", "oder", "или", "或", "或者", "或是", "または", "hoặc",
    "atau", "eller", "lub", "vagy", "ó", "czy", "sino", "sondern", "ili", "oppure",
}
# Words that introduce a conclusion or a consequence.
CONSEQUENCE = {"therefore", "thus", "hence", "consequently", "so"}
# Operators and comparisons that join two terms.
OPERATORS = {"+", "-", "/", "−", "–", "≥", "≤", "→", "⇒", "vs", "than", "as"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in OR:
        value = 6.4
    elif word in OTHER_DISJUNCTION:
        value = 2.4
    elif word in CONSEQUENCE:
        value = 1.9
    elif word in OPERATORS:
        value = 0.8
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 4378 (the component reads almost only this unit).

This is a weak, diffuse unit. Almost all of its variance is small, context-dependent
noise that no token rule captures, so this program only predicts the few token classes
where its average response departs from the usual value (about -0.03):

- the end-of-thinking token "</think>": reliably large and positive (about +1.5);
- the fullwidth comma "，": mildly positive (about +0.14);
- "+" right after a term (a letter, digit, closing bracket or superscript), as in
  algebra "a + b": mildly positive (about +0.14); other "+" uses: about -0.05;
- code comparison operators (==, !=, >=, <=, <, >) and "=": mildly negative (about -0.1).

Every other token predicts the usual value, -0.025.
"""

READS = ()

COMPARE = {"==", "!=", ">=", "<=", ">", "<", "="}
TERM_END = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789)}]|²³")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if cur == "</think>":
        value = 1.5
    elif cur == "，":
        value = 0.14
    elif cur == "+":
        value = 0.14 if prev[-1:] in TERM_END and prev else -0.05
    elif cur in COMPARE:
        value = -0.1
    else:
        value = -0.025
    return carry, value

"""MLP unit 4381 of layer 15 (this component's down_proj column), as a word rule.

The component is essentially one hidden unit of the layer-15 MLP. It fires on the
word that opens a comparison or a standard of comparison or conformity, i.e. the
word just before the thing something is compared with or conforms to:
  - "than" in "bigger than", "more fun than" (strongest);
  - "as" / "like" as comparison pivots: weak on their own, strong after
    "just" or "exactly" ("just like", "exactly as");
  - comparison and similarity words: similar, compared, unlike, reminiscent, resemble;
  - conformity and reach words: consistent (with), accordance (with), matches,
    exceed, beyond, fulfill, meet, replicate, reproduce;
  - the same idea in other languages: als, wie, comme, чем, 比, 按照, jak, como;
  - weakly, generic nouns that a relative clause or comparison follows: what,
    which, something, everything, things, the way, the manner, the style.
Everywhere else it predicts 0. Values are typical activations for each word.
"""

READS = ()

# Typical activation when the word is the pivot.
PIVOT = {
    "than": 2.4,
    "unlike": 3.0, "reminiscent": 4.6, "resemble": 4.2, "resembles": 3.2, "resembling": 5.0,
    "similar": 1.4, "compared": 1.3, "analogous": 1.3, "comparable": 1.1,
    "exceed": 3.3, "exceeds": 2.3, "replicate": 3.5, "fulfill": 2.8, "overcome": 2.1,
    "reproduce": 2.0, "beyond": 1.7, "consistent": 1.6, "accordance": 1.7, "matches": 1.5,
    "meet": 1.4, "meets": 1.3,
    "like": 1.3, "as": 0.7,
    "wie": 2.1, "comme": 1.9, "чем": 1.7, "比": 1.9, "按照": 2.4, "jak": 1.2, "como": 1.0,
    "als": 0.5,
}
# Weak activation on generic nouns and relative words that comparisons often follow.
GENERIC = {
    "what": 0.5, "which": 0.5, "something": 1.1, "everything": 1.3, "anything": 0.9,
    "things": 1.0, "topics": 1.7, "principles": 1.5, "way": 0.5, "manner": 1.0,
    "style": 0.6, "features": 1.0,
}
# "just like", "exactly as": the pivot is stronger right after these.
INTENSIFIERS = {"just", "exactly", "precisely"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = PIVOT.get(word, GENERIC.get(word, 0.0))
    if word in ("like", "as") and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            if prefix.token_strings[-2].strip().lower() in INTENSIFIERS:
                value = 5.0
    return carry, float(value)

"""Weak, token-level guess at MLP neuron 4390 of layer 15 (the component's activation).

The component is one hidden unit of the layer-15 MLP (its V points almost entirely at unit
4390), scaled by how large its down-projection column is. Its activation is positive and
spiky on formal notation and small on everyday prose. Most of its variance is context-specific,
so a token-level program captures only a little of it.

What this program does, in plain terms: it reads only the newest token and guesses a
small value from its kind:
  - verbs that say what a term means ("represents", "denotes", "suggests", ...): large
  - boolean and null literals (true, false, None, null, ...): medium
  - chat and tool-call markup (<tool_call>, <think>, assistant): medium
  - brackets and parentheses: medium, the most reliable single class
  - digits (more after a letter, as in codes like "B601/0"): small
  - other punctuation and symbols ($, `, #, //, ...): small
  - plain spaced words: about zero (a hair negative); everything else: zero
"""

from collections.abc import Mapping
import re

READS: tuple[str, ...] = ()

MEANING_VERBS = {
    " represents", " represent", " denotes", " denote", " indicates", " indicating",
    " suggests", " means", " meaning", " shows", " showing",
}
LITERALS = {"true", "false", "True", "False", "None", "null", "NULL", "boolean", "bool", "float"}
MARKUP = {"<tool_call>", "<tool_response>", "<think>", "assistant"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in MEANING_VERBS:
        value = 0.7
    elif tok in LITERALS:
        value = 0.4
    elif tok in MARKUP:
        value = 0.4
    elif re.fullmatch(r"\s?[\(\[\{\)\]\}]+", tok):
        value = 0.14
    elif re.fullmatch(r"\s?\d+", tok):
        value = 0.1 if prev[-1:].isalpha() else 0.05
    elif re.fullmatch(r"\s?[^\w\s]+", tok):
        value = 0.04
    elif re.fullmatch(r" [A-Za-z]+", tok):
        value = -0.01
    else:
        value = 0.0
    return carry, float(value)

"""Predicate-opening words: auxiliaries, copulas and degree adverbs.

Component layers.15.mlp.down_proj:4410 is positive where a clause's predicate is still open:
on a copula or auxiliary ("is", "was", "been", "must"), on a degree word or negation that
sits in the predicate ("very", "not", "also", "never"), and on the word right after one
of those ("has [changed]", "is [very] important"). It is strongest after a noun-phrase
subject and close to silent after a pronoun subject ("This is" -> low).
Everything else is predicted as 0.
"""

COPULA = {"is", "are", "was", "were", "be", "been", "being", "am"}
AUXILIARY = {"has", "have", "had", "will", "would", "can", "could", "must", "should", "may",
             "might", "shall", "do", "does", "did"}
DEGREE = {"very", "so", "much", "never", "often", "always", "also", "still", "too", "not",
          "really", "quite", "typically", "usually", "already", "only", "just", "even", "more"}
PRONOUN_SUBJECT = {"this", "that", "it", "they", "he", "she", "we", "i", "you", "which", "who",
                   "there", "these", "those", "what"}
OPENERS = COPULA | AUXILIARY | DEGREE

READS = ()


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in COPULA or word in AUXILIARY:
        value = 0.2 if before in PRONOUN_SUBJECT else 2.0
    elif word in DEGREE:
        value = 1.0
    elif before in OPENERS and word.isalpha():
        value = 1.0
    else:
        value = 0.0
    return carry, value

"""Component 4413 of layer 15's MLP down_proj, as a token-level guess.

It is a dense, weak feature. On average it is positive, higher on nouns, numbers
and the second or later piece of a split word, and lower on punctuation and
spaces. It also rises for nouns that sit inside a comma-separated list. This
program predicts that average pattern from the current token and the few
tokens before it.
"""
import re

import wordnet

READS = ()


def _is_noun(word):
    return bool(re.fullmatch(r"[A-Za-z]+", word)) and "noun" in wordnet.parts_of_speech(word.lower())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    docs = prefix.document_ids
    value = 0.08
    if re.fullmatch(r"[0-9]+", word):
        value += 0.09
    elif not re.search(r"\w", word):
        value -= 0.07
    if _is_noun(word):
        value += 0.09
        commas = sum(1 for t in prefix.token_strings[-12:-1] if t.strip() == ",")
        value += 0.05 * min(commas, 4)
    if len(prefix.token_strings) > 1 and docs[-2] == docs[-1]:
        previous = prefix.token_strings[-2]
        if not token.startswith(" ") and re.search(r"[A-Za-z]$", previous) and re.fullmatch(r"[A-Za-z]+", word):
            value += 0.2
    return carry, float(value)
